"""Thin command-line entry points for the independently installed CG application."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any


def _job(path: Path) -> dict[str, Any]:
    """Read an explicit job manifest generated by this application."""
    return json.loads(path.read_text())


def _prepare(args: argparse.Namespace) -> None:
    from corl2026_cg.data import prepare_dataset

    result = prepare_dataset(
        args.source,
        args.destination,
        entity_path=args.entity_path,
        entity_count=args.entity_count,
        active_profile=args.active_profile,
    )
    print(result)


def _inspect_instructions(args: argparse.Namespace) -> None:
    from corl2026_cg.data import inspect_instructions

    result = inspect_instructions(
        args.source, args.output, samples=args.samples, seed=args.seed, task=args.task
    )
    print(json.dumps(result, indent=2))


def _matrix(args: argparse.Namespace) -> None:
    from corl2026_cg.experiments.config import (
        ExecutionConfig,
        load_experiment,
        resolve_jobs,
        write_jobs,
    )
    from corl2026_cg.experiments.runner import run_jobs

    if args.jobs:
        if args.config or args.overrides or args.overwrite:
            raise ValueError("--jobs cannot be combined with --config, --set, or --overwrite")
        paths = [path.resolve() for path in args.jobs]
        jobs = [_job(path) for path in paths]
        overlaps = {ExecutionConfig.model_validate(job["execution"]).overlap for job in jobs}
        if len(overlaps) != 1:
            raise ValueError("All jobs in one invocation must use the same overlap setting")
        overlap = overlaps.pop()
    else:
        if args.config is None:
            raise ValueError("Supply --config or previously generated --jobs")
        spec = load_experiment(args.config, args.overrides)
        jobs = resolve_jobs(spec)
        overlap = spec.execution.overlap
        paths = [Path(job["directory"]) / "experiment.json" for job in jobs]
    if args.dry_run:
        print(json.dumps(jobs, indent=2))
        return
    if not args.jobs:
        paths = write_jobs(jobs, overwrite=args.overwrite)
    for path in paths:
        print(path, flush=True)
    if args.command == "run":
        run_jobs(paths, overlap=overlap, eval_only=args.eval_only, skip_eval=args.skip_eval)


def _train(args: argparse.Namespace) -> None:
    from robopolicy import RunConfig, Trainer, load_config, read_checkpoint

    from corl2026_cg.instructions import validate_dataset_profile
    from corl2026_cg.instructions.contracts import (
        policy_profile,
        validate_finetune_conditioning,
        validate_policy_conditioning,
    )

    job = _job(args.job) if args.job else None
    source = None
    if args.resume:
        if args.finetune_from:
            raise ValueError("--resume and --finetune-from are mutually exclusive")
        config = RunConfig.model_validate(read_checkpoint(args.resume)["run_config"])
    else:
        if job and args.finetune_from:
            raise ValueError("Set finetune_from in the experiment specification and regenerate")
        if job:
            saved = next(Path(job["run"]["logging"]["out_dir"]).glob("*.pt"), None)
            if saved is not None:
                raise FileExistsError(
                    f"Checkpoint already exists: {saved}; resume it or generate a new job"
                )
        config = RunConfig.model_validate(job["run"]) if job else load_config(args.config)
        source = args.finetune_from or (job["finetune_from"] if job else None)
    profile = policy_profile(config)
    if job:
        validate_policy_conditioning(
            config, job["family"], job["instruction"], job.get("conditioning", "static")
        )
        if profile and job.get("active_profile") != profile.to_dict():
            raise ValueError("Active instruction profile changed; regenerate the job")
    if profile:
        validate_dataset_profile(config, profile, split="train")
        if config.dataset.selection.val_fraction:
            validate_dataset_profile(config, profile, split="val")
    if source:
        validate_finetune_conditioning(
            config, RunConfig.model_validate(read_checkpoint(source)["run_config"])
        )
    if args.resume:
        trainer = Trainer.resume(args.resume)
    else:
        trainer = Trainer.finetune(config, source) if source else Trainer(config)
    try:
        trainer.fit()
    finally:
        trainer.close()


def _evaluate(args: argparse.Namespace) -> None:
    from corl2026_cg.evaluation import EvaluationConfig, evaluate
    from corl2026_cg.experiments.config import set_nested
    from corl2026_cg.tasks import build_task_set

    job = _job(args.job)
    task_set = build_task_set(
        job["family"], job["set_name"], job["instruction"], eval_set=job.get("eval_set")
    )
    if task_set.to_dict() != job["task_set"]:
        raise ValueError("Task-set definition changed since generation; regenerate explicitly")
    values = dict(job["evaluation"])
    for override in args.overrides:
        key, separator, value = override.partition("=")
        if not separator:
            raise ValueError("Evaluation overrides must be PATH=VALUE")
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            parsed = value
        set_nested(values, key, parsed)
    values["logging"]["wandb"].update(name=job["name"], group=job["group"])
    result = evaluate(
        args.checkpoint or Path(job["checkpoint"]),
        family=job["family"],
        instruction=job["instruction"],
        conditioning=job.get("conditioning", "static"),
        task_set=task_set,
        config=EvaluationConfig.model_validate(values),
        out_dir=args.output or Path(job["directory"]) / "evaluation",
    )
    print(json.dumps(result["aggregated"], indent=2))


def _loss(args: argparse.Namespace) -> None:
    from robopolicy import read_checkpoint
    from robopolicy.training.logging import LoggingConfig, RunIdentity, log_evaluation

    from corl2026_cg.experiments.losses import evaluate_losses

    job = _job(args.job) if args.job else None
    checkpoint = args.checkpoint or (Path(job["checkpoint"]) if job else None)
    family = args.family or (job["family"] if job else None)
    if checkpoint is None or family is None:
        raise ValueError("Supply --job, or both --checkpoint and --family")
    output = args.output or (Path(job["directory"]) / "losses.json" if job else None)
    if output is None:
        raise ValueError("Standalone loss evaluation requires --output")
    if output.exists():
        raise FileExistsError(f"Result already exists: {output}")
    instruction = args.instruction or (job["instruction"] if job else "full")
    result = evaluate_losses(
        checkpoint,
        family=family,
        instruction=instruction,
        conditioning=args.conditioning or (job.get("conditioning", "static") if job else None),
        dataset_root=args.dataset_root,
        samples=args.samples,
        batch_size=args.batch_size,
        seed=args.seed,
        device=args.device,
    )
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    payload = read_checkpoint(checkpoint)
    logging_values = job["evaluation"]["logging"] if job else payload["run_config"]["logging"]
    logging = LoggingConfig.model_validate(logging_values).model_copy(
        update={"out_dir": str(output.parent / "loss_logging")}
    )
    wandb_values = logging.wandb.model_dump()
    if job:
        wandb_values.update(name=f"{job['name']}-loss", group=job["group"])
    if args.local_only:
        wandb_values["enabled"] = False
    logging = logging.model_copy(update={"wandb": type(logging.wandb)(**wandb_values)})
    metrics = {
        f"loss/{split}/{key}": float(value)
        for split, values in result["splits"].items()
        for key, value in values.items()
        if isinstance(value, (int, float))
    }
    log_evaluation(
        logging,
        result,
        metrics,
        output,
        training_identity=RunIdentity.model_validate(payload["wandb"])
        if payload["wandb"]
        else None,
        checkpoint_step=payload["completed_updates"],
    )
    print(output)


def _report(args: argparse.Namespace) -> None:
    from corl2026_cg.experiments.report import write_report

    write_report(args.jobs, args.output)
    print(args.output / "report.md")


def main(argv: list[str] | None = None) -> None:
    """Parse arguments without importing optional learning or simulator runtimes."""
    parser = argparse.ArgumentParser(prog="cg", description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    prepare = commands.add_parser("prepare", help="Export immutable numeric CG datasets")
    prepare.add_argument("--source", type=Path, required=True)
    prepare.add_argument("--destination", type=Path, required=True)
    prepare.add_argument("--entity-path")
    prepare.add_argument("--entity-count", type=int)
    prepare.add_argument("--active-profile", choices=("l5_v1", "l4_infer_cont0_v1"))
    prepare.set_defaults(handler=_prepare)
    inspect = commands.add_parser(
        "inspect-instructions", help="Inspect reactive labels in aligned demonstration videos"
    )
    inspect.add_argument("--source", type=Path, required=True)
    inspect.add_argument("--output", type=Path, required=True)
    inspect.add_argument("--samples", type=int, default=4)
    inspect.add_argument("--seed", type=int, default=0)
    inspect.add_argument("--task")
    inspect.set_defaults(handler=_inspect_instructions)
    for name in ("generate", "run"):
        matrix = commands.add_parser(
            name,
            help="Resolve a matrix"
            if name == "generate"
            else "Run training and simulator evaluation",
        )
        matrix.add_argument("--config", type=Path)
        matrix.add_argument("--jobs", type=Path, nargs="+")
        matrix.add_argument("--set", dest="overrides", action="append", default=[])
        matrix.add_argument("--overwrite", action="store_true")
        matrix.add_argument("--dry-run", action="store_true")
        if name == "run":
            stages = matrix.add_mutually_exclusive_group()
            stages.add_argument("--eval-only", action="store_true")
            stages.add_argument("--skip-eval", action="store_true")
        matrix.set_defaults(handler=_matrix)
    train = commands.add_parser("train", help="Train, resume, or fine-tune a native core policy")
    source = train.add_mutually_exclusive_group(required=True)
    source.add_argument("--job", type=Path)
    source.add_argument("--config", type=Path)
    source.add_argument("--resume", type=Path)
    train.add_argument("--finetune-from", type=Path)
    train.set_defaults(handler=_train)
    evaluate = commands.add_parser("evaluate", help="Evaluate a job checkpoint in CG")
    evaluate.add_argument("--job", type=Path, required=True)
    evaluate.add_argument("--checkpoint", type=Path)
    evaluate.add_argument("--output", type=Path)
    evaluate.add_argument("--set", dest="overrides", action="append", default=[])
    evaluate.set_defaults(handler=_evaluate)
    loss = commands.add_parser("evaluate-loss", help="Measure seen/unseen offline policy losses")
    loss.add_argument("--job", type=Path)
    loss.add_argument("--checkpoint", type=Path)
    loss.add_argument("--family", choices=("l4", "l4_2s", "l5"))
    loss.add_argument("--conditioning", choices=("static", "active_v1"))
    loss.add_argument("--instruction")
    loss.add_argument("--output", type=Path)
    loss.add_argument("--dataset-root")
    loss.add_argument("--samples", type=int, default=500)
    loss.add_argument("--batch-size", type=int, default=50)
    loss.add_argument("--seed", type=int, default=0)
    loss.add_argument("--device", default="cuda:0")
    loss.add_argument("--local-only", action="store_true")
    loss.set_defaults(handler=_loss)
    report = commands.add_parser("report", help="Summarize explicit experiment directories")
    report.add_argument("--jobs", type=Path, nargs="+", required=True)
    report.add_argument("--output", type=Path, required=True)
    report.set_defaults(handler=_report)
    args = parser.parse_args(argv)
    args.handler(args)
